-- Studio Co-op: Migration 027 — Seed Empire Aerial Arts real schedule
-- Source: Mindbody public consumer API (prod-mkt-gateway.mindbody.io), fetched 2026-06-12 NZT.
-- Teachers are DISPLAY-ONLY user rows (no auth accounts; emails use import alias).
-- Replace/merge these rows when real teachers are invited during pilot onboarding.

-- ===== Teachers (display-only) =====
on conflict (id) do update set name = excluded.name;

-- ===== Weekly class templates (day_of_week: 0=Sunday) =====
on conflict (id) do update set
  name = excluded.name, teacher_id = excluded.teacher_id, day_of_week = excluded.day_of_week,
  start_time = excluded.start_time, duration_min = excluded.duration_min,
  max_capacity = excluded.max_capacity, active = true;

-- ===== Concrete instances (next 14 days, exact Mindbody dates incl. teacher subs) =====
on conflict (template_id, date) do update set
  teacher_id = excluded.teacher_id, start_time = excluded.start_time,
  end_time = excluded.end_time, max_capacity = excluded.max_capacity;
